  /**
   * @ignore
   * @method
   * @name hibachi#fetchOrdersByStatus
   * @description fetch orders filtered by terminal status
   * @see https://api-doc.hibachi.xyz/#0ca35e79-a80e-4a91-bd32-de3fc2b0b1fa
   * @param {string} status exchange specific terminal status
   * @param {string} [symbol] unified market symbol to filter by
   * @param {int} [since] timestamp in ms of the earliest order
   * @param {int} [limit] the maximum number of orders to return
   * @param {object} [params] extra parameters
   * @param {int} [params.until] timestamp in ms of the latest order
   * @param {string} [params.cursorOrderId] pagination cursor, returns orders
   * with orderId strictly less than this value
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<ccxt::any>
  fetchOrdersByStatus(ccxt::any status, ccxt::any symbol = ccxt::any{},
                      ccxt::any since = ccxt::any{},
                      ccxt::any limit = ccxt::any{},
                      ccxt::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = ccxt::any{};
                 ccxt::any request = ccxt::dict{
                     {std::string("accountId"), this->getAccountId()},
                 };
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 if (isTrue(!isEqual(status, ccxt::any{}))) {
                   ::setValue(request, std::string("status"), status);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 ccxt::any until = ccxt::any{};
                 ccxt::any untilparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOrdersByStatus"),
                     std::string("until"));
                 until = ::getValue(untilparamsVariable, 0);
                 params = ::getValue(untilparamsVariable, 1);
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   ::setValue(request, std::string("endTime"), until);
                 }
                 ccxt::any response =
                     awaitValue(this->privateGetTradeOrdersHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "hasMore": false,
                 //         "orders": [
                 //             {
                 //                 "accountId": 128,
                 //                 "avgFillPrice": "2900.000000",
                 //                 "closedAt": 1777811627000,
                 //                 "createdAt": 1777811620000,
                 //                 "filledQuantity": "1.200000000",
                 //                 "orderFlags": null,
                 //                 "orderId": "596002791293190100",
                 //                 "orderType": "MARKET",
                 //                 "parentOrderId": null,
                 //                 "price": null,
                 //                 "side": "BID",
                 //                 "sourceType": "regular",
                 //                 "status": "Filled",
                 //                 "symbol": "ETH/USDT-P",
                 //                 "totalQuantity": "1.200000000",
                 //                 "triggerDirection": null,
                 //                 "triggerPrice": null
                 //             }
                 //         ]
                 //     }
                 //
                 ccxt::any orders = this->safeList(
                     response, std::string("orders"), ccxt::list{});
                 ccxt::any parsedOrders = this->parseOrders(orders, market);
                 return this->filterBySymbolSinceLimit(parsedOrders, symbol,
                                                       since, limit);
               })
        .share();
  }

