  /**
   * @method
   * @name hibachi#fetchDeposits
   * @description fetch deposits made to account
   * @see https://api-doc.hibachi.xyz/#35125e3f-d154-4bfd-8276-a48bb1c62020
   * @param {string} [code] unified currency code
   * @param {int} [since] filter by earliest timestamp (ms)
   * @param {int} [limit] maximum number of deposits to be returned
   * @param {object} [params] extra parameters to be passed to API
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  fetchDeposits(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any transactions =
                            awaitValue(this->fetchDepositsWithdrawals(
                                code, since, ccxt::any{}, params));
                        ccxt::any deposits =
                            this->filterBy(transactions, std::string("type"),
                                           std::string("deposit"));
                        return this->filterBySinceLimit(
                            deposits, since, limit, std::string("timestamp"));
                      })
        .share();
  }

